/**
 * Verified surah → Wikidata / Wikipedia map (generated by scripts/build-wikidata-surahs.mjs from the
 * Wikidata SPARQL endpoint; every entry agrees on the surah number across ≥2 independent signals).
 */
import data from './wikidata-surahs.json'

type Entry = { wikidata: string; en?: string; bn?: string; ar?: string }
const surahs = data.surahs as Record<string, Entry>

export const QURAN_WIKIDATA = 'https://www.wikidata.org/wiki/Q428'
export const QURAN_WIKIPEDIA = { en: 'https://en.wikipedia.org/wiki/Quran', bn: 'https://bn.wikipedia.org/wiki/%E0%A6%95%E0%A7%81%E0%A6%B0%E0%A6%86%E0%A6%A8' }

export const surahWikidata = (id: number): Entry | null => surahs[String(id)] ?? null

/** schema.org `sameAs` URLs for a surah: Wikidata item + Wikipedia article(s), Bangla first on /bn. */
export function surahSameAs(id: number, locale: 'en' | 'bn' = 'en'): string[] {
  const e = surahWikidata(id)
  if (!e) return []
  const wiki = locale === 'bn' ? [e.bn, e.en, e.ar] : [e.en, e.bn, e.ar]
  return [`https://www.wikidata.org/wiki/${e.wikidata}`, ...wiki.filter((x): x is string => !!x)]
}
